Here is the commit message:
smb: client: fix oops due to uninitialised var in
 smb2_unlink()

If SMB2_open_init() or SMB2_close_init() fails (e.g. reconnect), the
iovs set @rqst will be left uninitialised, hence calling
SMB2_open_free(), SMB2_close_free() or smb2_set_related() on them will
oops.

Fix this by initialising @close_iov and @open_iov before setting them
in @rqst.

Reported-by: Thiago Becker <tbecker@redhat.com>
Fixes: 1cf9f2a6a544 ("smb: client: handle unlink(2) of files open by different clients")
Signed-off-by: Paulo Alcantara (Red Hat) <pc@manguebit.org>
Cc: David Howells <dhowells@redhat.com>
Cc: linux-cifs@vger.kernel.org
Cc: stable@vger.kernel.org
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
The iov structures (open_iov and close_iov) used in the compound request for SMB2 unlink were not initialized before being passed to SMB2_open_init() and SMB2_close_init(). If these initialization functions fail (e.g., due to reconnect), the cleanup code (SMB2_open_free, SMB2_close_free, smb2_set_related) would operate on uninitialized data, causing a kernel oops.

Here is the patch:

 int
 smb2_unlink(const unsigned int xid, struct cifs_tcon *tcon, const char *name,
 	    struct cifs_sb_info *cifs_sb, struct dentry *dentry)
 {
 	struct kvec open_iov[SMB2_CREATE_IOV_SIZE];
 	__le16 *utf16_path __free(kfree) = NULL;
 	int retries = 0, cur_sleep = 0;
 	struct TCP_Server_Info *server;
 	struct cifs_open_parms oparms;
 	struct smb2_create_req *creq;
 	struct inode *inode = NULL;
 	struct smb_rqst rqst[2];
 	struct kvec rsp_iov[2];
 	struct kvec close_iov;
 	int resp_buftype[2];
 	struct cifs_fid fid;
 	int flags = 0;
 	__u8 oplock;
 	int rc;

 	utf16_path = cifs_convert_path_to_utf16(name, cifs_sb);
 	if (!utf16_path)
 		return -ENOMEM;

 	if (smb3_encryption_required(tcon))
 		flags |= CIFS_TRANSFORM_REQ;
 again:
 	oplock = SMB2_OPLOCK_LEVEL_NONE;
 	server = cifs_pick_channel(tcon->ses);

 	memset(rqst, 0, sizeof(rqst));
 	memset(resp_buftype, 0, sizeof(resp_buftype));
 	memset(rsp_iov, 0, sizeof(rsp_iov));

+	memset(open_iov, 0, sizeof(open_iov));
 	rqst[0].rq_iov = open_iov;
 	rqst[0].rq_nvec = ARRAY_SIZE(open_iov);

 	oparms = CIFS_OPARMS(cifs_sb, tcon, name, DELETE | FILE_READ_ATTRIBUTES,
 			     FILE_OPEN, CREATE_DELETE_ON_CLOSE |
 			     OPEN_REPARSE_POINT, ACL_NO_MODE);
 	oparms.fid = &fid;

 	if (dentry) {
 		inode = d_inode(dentry);
 		if (CIFS_I(inode)->lease_granted && server->ops->get_lease_key) {
 			oplock = SMB2_OPLOCK_LEVEL_LEASE;
 			server->ops->get_lease_key(inode, &fid);
 		}
 	}

 	rc = SMB2_open_init(tcon, server,
 			    &rqst[0], &oplock, &oparms, utf16_path);
 	if (rc)
 		goto err_free;
 	smb2_set_next_command(tcon, &rqst[0]);
 	creq = rqst[0].rq_iov[0].iov_base;
 	creq->ShareAccess = FILE_SHARE_DELETE_LE;

+	memset(&close_iov, 0, sizeof(close_iov));
 	rqst[1].rq_iov = &close_iov;
 	rqst[1].rq_nvec = 1;

 	rc = SMB2_close_init(tcon, server, &rqst[1],
 			     COMPOUND_FID, COMPOUND_FID, false);
-	smb2_set_related(&rqst[1]);
 	if (rc)
 		goto err_free;
+	smb2_set_related(&rqst[1]);

 	if (retries) {
 		/* Back-off before retry */
 		if (cur_sleep)
 			msleep(cur_sleep);
 		for (int i = 0; i < ARRAY_SIZE(rqst);  i++)
 			smb2_set_replay(server, &rqst[i]);
 	}

 	rc = compound_send_recv(xid, tcon->ses, server, flags,
 				ARRAY_SIZE(rqst), rqst,
 				resp_buftype, rsp_iov);
 	SMB2_open_free(&rqst[0]);
 	SMB2_close_free(&rqst[1]);
 	free_rsp_buf(resp_buftype[0], rsp_iov[0].iov_base);
 	free_rsp_buf(resp_buftype[1], rsp_iov[1].iov_base);

 	if (is_replayable_error(rc) &&
 	    smb2_should_replay(tcon, &retries, &cur_sleep))
 		goto again;

 	/* Retry compound request without lease */
 	if (rc == -EINVAL && dentry) {
 		dentry = NULL;
 		retries = 0;
 		cur_sleep = 0;
 		goto again;
 	}
 	/*
 	 * If dentry (hence, inode) is NULL, lease break is going to
 	 * take care of degrading leases on handles for deleted files.
 	 */
 	if (!rc && inode)
 		cifs_mark_open_handles_for_deleted_file(inode, name);

 	return rc;

 err_free:
 	SMB2_open_free(&rqst[0]);
 	SMB2_close_free(&rqst[1]);
 	free_rsp_buf(resp_buftype[0], rsp_iov[0].iov_base);
 	free_rsp_buf(resp_buftype[1], rsp_iov[1].iov_base);
 	return rc;
 }



